<script setup lang="tsx">
import { ref, computed, onMounted, watch, onBeforeUnmount, nextTick, type WatchStopHandle } from "vue";
import { useRoute } from "vue-router";
import router from "@/router";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, ShowErrorTips, ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import {
  GetDiscuss,
  ParseDiscuss,
  GetDiscussCommentList,
  ParseDiscussComment,
  GetDiscussCommentImageToken,
  PostDiscussCommentCreate,
  PostDiscussCommentEdit,
  PostDiscussCommentDelete,
  GetDiscussReplyList,
} from "@/apis/discuss.ts";
import type {
  DiscussComment,
  DiscussCommentEditRequest,
  DiscussCommentView,
  DiscussView,
} from "@/types/discuss.ts";
import { handleOpenUsername } from "@/util/router.ts";

import { useWebStyleStore } from "@/stores/webStyle.ts";

import { useUserStore } from "@/stores/user.ts";
import { AuthType } from "@/auth";
import { GetContestProblemIndexStr } from "@/apis/contest.ts";
import { HandleR2ImageUpload, UploadImageCallbackUrl } from "@/util/md-editor-v3.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

const props = defineProps<{ discussId?: string }>();

const route = useRoute();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

let viewActive = false;
let watchHandle: WatchStopHandle | null = null;

const webStyleStore = useWebStyleStore();
const userStore = useUserStore();

const discussContent = ref("");
// 与 props.discussId 区分：这里是解析后的当前讨论 id
const currentDiscussId = ref(0);
const discussLoading = ref(false);
const discussData = ref<DiscussView | null>(null);

const dataLoading = ref(false);

// 顶层评论编辑器状态
const commentSubmitting = ref(false);
const editCommentId = ref(0);
const editCommentContent = ref("");

// 顶层回复父评论 ID（0 表示直接在底部编辑器发表新评论）
const topLevelReplyParent = ref(0);

let currentPage = 1;
let currentPageSize = 20;

// 楼中楼预览数量：首次加载时显示的回复条数，超过该数量才需要用户手动点击查看全部
const REPLY_PREVIEW_COUNT = 3;
// 楼中楼完整模式分页大小
const REPLY_FULL_PAGE_SIZE = 10;

const pagination = ref({
  current: 1,
  pageSize: 20,
  total: 0,
  defaultPageSize: currentPageSize,
  defaultCurrent: currentPage,
  pageSizeOptions: [20, 50],
});

const discussCommentList = ref([] as DiscussCommentView[]);

// 楼中楼状态管理
interface ReplyState {
  list: DiscussCommentView[];
  total: number;
  page: number;
  pageSize: number;
  order: "ASC" | "DESC";
  loading: boolean;
  expanded: boolean;
  // 是否为预览模式（只显示前几条，需要点击按钮查看全部）
  previewMode: boolean;
  // 就地编辑/回复状态
  editingReplyId: number;
  editingReplyContent: string;
  // 回复某条楼中楼回复
  replyingToId: number;
  replyingContent: string;
  submitting: boolean;
}

const replyStates = ref<Record<number, ReplyState>>({});

// 高亮的评论 ID（用于锚点定位）
const highlightedCommentId = ref(0);

const hasManageDiscussAuth = computed(() => {
  return userStore.hasAuth(AuthType.ManageDiscuss);
});

const hasEditDiscussAuth = computed(() => {
  return (
    userStore.hasAuth(AuthType.ManageDiscuss) ||
    (discussData.value && userStore.getUserId == discussData.value.inserter)
  );
});

const handleClickEdit = () => {
  router.push({
    name: "discuss-edit",
    params: {
      discussId: currentDiscussId.value,
    },
  });
};

const renderCommentTotalContent = () => {
  return <div class="t-pagination__total">{`共 ${pagination.value.total} 条回复`}</div>;
};

// 获取或初始化楼中楼状态
const getReplyState = (parentId: number): ReplyState => {
  if (!replyStates.value[parentId]) {
    replyStates.value[parentId] = {
      list: [],
      total: 0,
      page: 1,
      pageSize: REPLY_PREVIEW_COUNT,
      order: "ASC",
      loading: false,
      expanded: false,
      previewMode: true,
      editingReplyId: 0,
      editingReplyContent: "",
      replyingToId: 0,
      replyingContent: "",
      submitting: false,
    };
  }
  return replyStates.value[parentId];
};

// 加载楼中楼回复列表
const fetchReplyList = async (parentId: number, needLoading: boolean = true) => {
  const state = getReplyState(parentId);
  if (needLoading) {
    state.loading = true;
  }
  try {
    const res = await GetDiscussReplyList(parentId, state.page, state.pageSize, state.order);
    if (res.code === 0) {
      const responseList = res.data.list as DiscussComment[];
      const parsedList: DiscussCommentView[] = [];
      if (responseList) {
        for (let i = 0; i < responseList.length; i++) {
          parsedList.push(ParseDiscussComment(responseList[i]));
        }
      }
      state.list = parsedList;
      state.total = res.data.total_count;
    } else if (needLoading) {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      state.loading = false;
    }
  }
};

// 展开/收起楼中楼
const handleToggleReplies = async (parentId: number) => {
  const state = getReplyState(parentId);
  if (state.expanded) {
    // 收起
    state.expanded = false;
  } else {
    // 展开：恢复到预览模式
    state.expanded = true;
    state.previewMode = true;
    state.pageSize = REPLY_PREVIEW_COUNT;
    state.page = 1;
    await fetchReplyList(parentId);
  }
};

// 查看全部回复（从预览模式切换到完整模式）
const handleViewAllReplies = async (parentId: number) => {
  const state = getReplyState(parentId);
  state.previewMode = false;
  state.pageSize = REPLY_FULL_PAGE_SIZE;
  state.page = 1;
  await fetchReplyList(parentId);
};

// 切换楼中楼排序
const handleToggleReplyOrder = async (parentId: number) => {
  const state = getReplyState(parentId);
  state.order = state.order === "ASC" ? "DESC" : "ASC";
  state.page = 1;
  await fetchReplyList(parentId);
};

// 楼中楼分页变化
const onReplyPageChange = async (parentId: number, pageInfo: { current: number; pageSize: number }) => {
  const state = getReplyState(parentId);
  state.page = pageInfo.current;
  state.pageSize = pageInfo.pageSize;
  await fetchReplyList(parentId);
};

// 开始就地回复楼中楼
const handleReplyToReply = (parentId: number, replyId: number, _replyToUsername?: string) => {
  const state = getReplyState(parentId);
  // 切换回复对象
  if (state.replyingToId === replyId) {
    state.replyingToId = 0;
    state.replyingContent = "";
  } else {
    state.replyingToId = replyId;
    state.replyingContent = "";
    // 清除编辑状态
    state.editingReplyId = 0;
    state.editingReplyContent = "";
  }
};

// 开始编辑楼中楼回复
const handleEditReply = (parentId: number, replyId: number, content: string) => {
  const state = getReplyState(parentId);
  state.editingReplyId = replyId;
  state.editingReplyContent = content;
  // 清除回复状态
  state.replyingToId = 0;
  state.replyingContent = "";
};

// 取消楼中楼编辑/回复
const handleCancelReplyEditor = (parentId: number) => {
  const state = getReplyState(parentId);
  state.editingReplyId = 0;
  state.editingReplyContent = "";
  state.replyingToId = 0;
  state.replyingContent = "";
};

// 保存楼中楼回复（新建或编辑）
const handleSaveReplyInLounge = async (parentId: number) => {
  const state = getReplyState(parentId);
  state.submitting = true;
  try {
    if (state.editingReplyId) {
      // 编辑现有回复
      const postData = {
        id: state.editingReplyId,
        discuss_id: currentDiscussId.value,
        content: state.editingReplyContent,
      } as DiscussCommentEditRequest;
      const res = await PostDiscussCommentEdit(postData);
      if (res.code !== 0) {
        ShowErrorTips(globalProperties, res.code);
        return;
      }
      ShowTextTipsSuccess(globalProperties, "编辑成功");
      state.editingReplyId = 0;
      state.editingReplyContent = "";
    } else {
      // 新回复
      const postData = {
        discuss_id: currentDiscussId.value,
        content: state.replyingContent,
        parent_id: parentId,
        reply_to_comment_id: state.replyingToId || undefined,
      } as DiscussCommentEditRequest;
      const res = await PostDiscussCommentCreate(postData);
      if (res.code !== 0) {
        ShowErrorTips(globalProperties, res.code);
        return;
      }
      ShowTextTipsSuccess(globalProperties, "回复成功");
      state.replyingToId = 0;
      state.replyingContent = "";
      // 新建回复后，如果当前是预览模式，切换到完整模式以确保用户能看到自己的回复
      if (state.previewMode) {
        state.previewMode = false;
        state.pageSize = REPLY_FULL_PAGE_SIZE;
        state.page = 1;
      }
    }
    // 刷新楼中楼列表
    await fetchReplyList(parentId);
    // 更新顶层评论的 reply_count
    const parentComment = discussCommentList.value.find((c) => c.id === parentId);
    if (parentComment) {
      parentComment.replyCount = state.total;
    }
  } finally {
    state.submitting = false;
  }
};

// 删除楼中楼回复
const handleDeleteReply = async (parentId: number, replyId: number) => {
  const state = getReplyState(parentId);
  state.submitting = true;
  try {
    const res = await PostDiscussCommentDelete(replyId);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "删除成功");
    await fetchReplyList(parentId);
    const parentComment = discussCommentList.value.find((c) => c.id === parentId);
    if (parentComment) {
      parentComment.replyCount = state.total;
    }
  } finally {
    state.submitting = false;
  }
};

// 删除顶层评论
const handleDeleteComment = async (commentId: number) => {
  try {
    const res = await PostDiscussCommentDelete(commentId);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "删除成功");
    if (currentPage === 1) {
      await fetchCommentList({ current: 1, pageSize: currentPageSize }, true);
    } else {
      await router.push({
        query: {
          current: 1,
        },
      });
    }
  } catch (err) {
    console.error(err);
    ShowErrorTips(globalProperties, GetCommonErrorCode());
  }
};

// 顶层评论的就地回复（在评论下方展开编辑器）
const handleReplyToComment = (commentId: number) => {
  // 切换回复状态
  if (topLevelReplyParent.value === commentId) {
    topLevelReplyParent.value = 0;
    editCommentContent.value = "";
    editCommentId.value = 0;
  } else {
    topLevelReplyParent.value = commentId;
    editCommentContent.value = "";
    editCommentId.value = 0;
    // 自动展开楼中楼
    const state = getReplyState(commentId);
    if (!state.expanded) {
      handleToggleReplies(commentId);
    }
  }
};

// 顶层评论的就地编辑
const handleGotoEditComment = (id: number, content: string) => {
  editCommentId.value = id;
  editCommentContent.value = content;
  topLevelReplyParent.value = 0;
  const discussEditor = document.getElementById("discuss-comment-editor");
  if (discussEditor) {
    discussEditor.scrollIntoView({ behavior: "smooth" });
  }
};

const handleClickClear = () => {
  editCommentId.value = 0;
  editCommentContent.value = "";
  topLevelReplyParent.value = 0;
};

const handleSaveReply = async () => {
  commentSubmitting.value = true;

  try {
    if (editCommentId.value) {
      // 编辑顶层评论
      const postData = {
        id: editCommentId.value,
        discuss_id: currentDiscussId.value,
        content: editCommentContent.value,
      } as DiscussCommentEditRequest;
      const res = await PostDiscussCommentEdit(postData);
      if (res.code !== 0) {
        ShowErrorTips(globalProperties, res.code);
        return;
      }

      ShowTextTipsSuccess(globalProperties, "编辑成功");

      editCommentId.value = 0;
      editCommentContent.value = "";

      if (currentPage === 1) {
        await fetchCommentList({ current: 1, pageSize: currentPageSize }, true);
      } else {
        await router.push({
          query: {
            current: 1,
          },
        });
      }
      const commentDivider = document.getElementById("comment-divider");
      if (commentDivider) {
        commentDivider.scrollIntoView({ behavior: "smooth" });
      }
    } else if (topLevelReplyParent.value) {
      // 在顶层评论下回复（楼中楼）
      const postData = {
        discuss_id: currentDiscussId.value,
        content: editCommentContent.value,
        parent_id: topLevelReplyParent.value,
        reply_to_comment_id: topLevelReplyParent.value, // 回复的是顶层评论
      } as DiscussCommentEditRequest;
      const res = await PostDiscussCommentCreate(postData);
      if (res.code !== 0) {
        ShowErrorTips(globalProperties, res.code);
        return;
      }

      ShowTextTipsSuccess(globalProperties, "回复成功");

      const parentId = topLevelReplyParent.value;
      editCommentContent.value = "";
      topLevelReplyParent.value = 0;

      // 刷新楼中楼
      const state = getReplyState(parentId);
      state.expanded = true;
      state.page = 1;
      await fetchReplyList(parentId);
      // 更新 reply_count
      const parentComment = discussCommentList.value.find((c) => c.id === parentId);
      if (parentComment) {
        parentComment.replyCount = state.total;
      }
    } else {
      // 发表新顶层评论
      const postData = {
        discuss_id: currentDiscussId.value,
        content: editCommentContent.value,
      } as DiscussCommentEditRequest;
      const res = await PostDiscussCommentCreate(postData);
      if (res.code !== 0) {
        ShowErrorTips(globalProperties, res.code);
        return;
      }

      ShowTextTipsSuccess(globalProperties, "发表成功");

      editCommentId.value = 0;
      editCommentContent.value = "";

      if (currentPage === 1) {
        await fetchCommentList({ current: 1, pageSize: currentPageSize }, true);
      } else {
        await router.push({
          query: {
            current: 1,
          },
        });
      }
      const commentDivider = document.getElementById("comment-divider");
      if (commentDivider) {
        commentDivider.scrollIntoView({ behavior: "smooth" });
      }
    }
  } finally {
    commentSubmitting.value = false;
  }
};

const handleUploadImg = async (files: File[], callback: (urls: UploadImageCallbackUrl[]) => void) => {
  commentSubmitting.value = true;
  await HandleR2ImageUpload(files, callback, globalProperties, () => {
    return GetDiscussCommentImageToken(currentDiscussId.value, editCommentId.value);
  });
  commentSubmitting.value = false;
};

// 楼中楼编辑器图片上传
const handleUploadImgInLounge = async (
  parentId: number,
  files: File[],
  callback: (urls: UploadImageCallbackUrl[]) => void
) => {
  const state = getReplyState(parentId);
  state.submitting = true;
  const replyCommentId = state.editingReplyId || 0;
  await HandleR2ImageUpload(files, callback, globalProperties, () => {
    return GetDiscussCommentImageToken(currentDiscussId.value, replyCommentId);
  });
  state.submitting = false;
};

const fetchCommentList = async (
  paginationInfo: { current: number; pageSize: number },
  needLoading: boolean
) => {
  if (needLoading) {
    dataLoading.value = true;
  }
  try {
    const { current, pageSize } = paginationInfo;
    const res = await GetDiscussCommentList(currentDiscussId.value, current, pageSize);
    discussCommentList.value = [];
    if (res.code === 0) {
      const responseList = res.data.list as DiscussComment[];
      if (responseList) {
        for (let i = 0; i < responseList.length; i++) {
          const item = responseList[i];
          const result = ParseDiscussComment(item);
          discussCommentList.value?.push(result);
        }
      }
      pagination.value = { ...pagination.value, total: res.data.total_count };

      // 预览回复：对所有有回复的评论，自动加载前 REPLY_PREVIEW_COUNT 条
      const previewPromises: Promise<void>[] = [];
      for (const comment of discussCommentList.value) {
        if (comment.replyCount > 0) {
          const state = getReplyState(comment.id);
          state.expanded = true;
          state.previewMode = true;
          state.pageSize = REPLY_PREVIEW_COUNT;
          state.page = 1;
          previewPromises.push(fetchReplyList(comment.id, false));
        }
      }
      await Promise.all(previewPromises);

      // 处理锚点定位
      await nextTick();
      handleAnchorHighlight();
    } else {
      if (needLoading) {
        ShowErrorTips(globalProperties, res.code);
      }
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      dataLoading.value = false;
    }
  }
};

// 处理 URL 锚点定位高亮
const handleAnchorHighlight = async () => {
  const hash = window.location.hash;
  const match = hash.match(/comment-(\d+)/);
  if (match) {
    const commentId = parseInt(match[1]);
    if (commentId > 0) {
      highlightedCommentId.value = commentId;
      await nextTick();
      const element = document.getElementById(`comment-${commentId}`);
      if (element) {
        element.scrollIntoView({ behavior: "smooth", block: "center" });
      }
      // 5 秒后取消高亮
      setTimeout(() => {
        highlightedCommentId.value = 0;
      }, 5000);
    }
  }
};

// 复制评论链接到剪贴板
const handleCopyCommentLink = async (commentId: number) => {
  const link = `${window.location.origin}/discuss/${currentDiscussId.value}#comment-${commentId}`;
  try {
    await navigator.clipboard.writeText(link);
    ShowTextTipsSuccess(globalProperties, "链接已复制");
  } catch (err) {
    // 降级方案：使用临时 textarea
    const textarea = document.createElement("textarea");
    textarea.value = link;
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    textarea.select();
    try {
      document.execCommand("copy");
      ShowTextTipsSuccess(globalProperties, "链接已复制");
    } catch (e) {
      ShowTextTipsError(globalProperties, "复制失败，请手动复制");
    }
    document.body.removeChild(textarea);
  }
};

const onPageChange = async (pageInfo: { current: number; pageSize: number }) => {
  await router.push({
    query: { ...route.query, page: pageInfo.current, page_size: pageInfo.pageSize },
  });
};

onMounted(async () => {
  viewActive = true;

  currentDiscussId.value = Number(props.discussId);
  if (!currentDiscussId.value) {
    if (Array.isArray(route.params.discussId)) {
      currentDiscussId.value = Number(route.params.discussId[0]);
    } else {
      currentDiscussId.value = Number(route.params.discussId);
    }
  }
  if (!currentDiscussId.value) {
    ShowTextTipsError(globalProperties, "讨论不存在");
    await router.push({ name: "discuss" });
    return;
  }

  discussLoading.value = true;

  const res = await GetDiscuss(currentDiscussId.value);
  if (res.code !== 0) {
    discussLoading.value = false;
    ShowErrorTips(globalProperties, res.code);
    await router.push({ name: "discuss" });
    return;
  }

  discussData.value = ParseDiscuss(res.data.discuss);

  webStyleStore.setTitle(discussData.value.title + " - " + webStyleStore.getTitle);

  discussContent.value = discussData.value.content as string;

  discussLoading.value = false;

  watchHandle = watch(
    () => route.query,
    (newQuery) => {
      if (!viewActive) {
        return;
      }
      const queryPage = parseInt(newQuery.page as string) || pagination.value.defaultCurrent;
      const queryPageSize =
        parseInt(newQuery.page_size as string) || pagination.value.defaultPageSize;
      currentPage = queryPage;
      currentPageSize = queryPageSize;
      pagination.value = {
        ...pagination.value,
        current: currentPage,
        pageSize: currentPageSize,
      };
      fetchCommentList({ current: currentPage, pageSize: currentPageSize }, true);
    },
    { immediate: true }
  );
});

onBeforeUnmount(() => {
  viewActive = false;

  if (watchHandle) {
    watchHandle();
  }
});
</script>

<template>
  <t-loading :loading="discussLoading">
    <t-row class="dida-main-content">
      <t-col :span="isMobile ? 12 : 8">
        <div
          v-if="discussData?.problemTitle || discussData?.contestTitle"
          style="margin: 20px"
        >
          <t-breadcrumb max-item-width="300">
            <template v-if="discussData?.contestTitle">
              <t-breadcrumb-item
                :to="{ name: 'contest-detail', params: { contestId: discussData?.contestId } }"
              >
                {{ discussData?.contestTitle }}
              </t-breadcrumb-item>
              <t-breadcrumb-item
                v-if="discussData?.contestProblemIndex"
                :to="{
                  name: 'contest-problem-detail',
                  params: {
                    contestId: discussData?.contestId,
                    problemIndex: discussData?.contestProblemIndex,
                  },
                }"
              >
                {{ GetContestProblemIndexStr(discussData?.contestProblemIndex) }} -
                {{ discussData?.problemTitle }}
              </t-breadcrumb-item>
            </template>
            <template v-else>
              <t-breadcrumb-item :to="{ name: 'discuss-list-problem' }"> 题目讨论</t-breadcrumb-item>
              <t-breadcrumb-item
                :to="{ name: 'problem-detail', params: { problemKey: discussData?.problemKey } }"
              >
                {{ discussData?.problemTitle }}
              </t-breadcrumb-item>
            </template>
          </t-breadcrumb>
        </div>

        <t-card style="margin: 10px" :header="discussData?.title" :header-bordered="true">
          <md-preview :model-value="discussContent" preview-theme="cyanosis"></md-preview>
        </t-card>
        <t-divider id="comment-divider">评论区</t-divider>
        <t-card
          v-for="(comment, index) in discussCommentList"
          :id="`comment-${comment.id}`"
          :key="index"
          style="margin: 10px"
          header-bordered
          :class="{ 'comment-highlighted': highlightedCommentId === comment.id }"
        >
          <template #header>
            <div class="dida-operation-container">
              <t-space>
                <t-avatar
                  shape="round"
                  size="32px"
                  :image="comment?.avatarUrl"
                  :hide-on-load-failed="false"
                />
                <t-button
                  variant="text"
                  @click="
                    () => {
                      handleOpenUsername(router, comment.inserterUsername);
                    }
                  "
                  >{{ comment.inserterNickname }}</t-button
                >
                <span style="line-height: 32px">{{ comment.insertTime }}</span>
              </t-space>
            </div>
            <div class="dida-operation-container">
              <t-space>
                <t-button variant="outline" @click="handleCopyCommentLink(comment.id)">复制链接</t-button>
